// Reports/WorkSummary.cs
public sealed class WorkSummary
{
    public WorkSummary(int employeeId, double hours)
    {
        EmployeeId = employeeId;
        Hours = hours;
    }

    public int EmployeeId { get; }
    public double Hours { get; }
}

// Reports/ClockEntryAnalytics.cs
public static class ClockEntryAnalytics
{
    public static IReadOnlyList<WorkSummary> HoursByEmployee(IEnumerable<ClockEntry> entries)
    {
        IEnumerable<ClockEntry> completedEntries =
            entries.Where(entry => entry.Clockout is not null);
        var employeeGroups = completedEntries.GroupBy(entry => entry.EmployeeId);
        var summaries = employeeGroups.Select(group => new WorkSummary(
            group.Key,
            group.Sum(entry => entry.GetDuration()?.TotalHours ?? 0)));
        var orderedSummaries = summaries.OrderBy(summary => summary.EmployeeId);
        return orderedSummaries.ToList();
    }

    public static IEnumerable<string> EmployeeLabels(
        IEnumerable<Employee> employees,
        IEnumerable<WorkSummary> summaries)
    {
        IEnumerable<string> labels = employees.Join(
            summaries,
            employee => employee.Identity,
            summary => summary.EmployeeId,
            (employee, summary) => $"{employee.Name}: {summary.Hours:F1} hours");
        return labels;
    }
}

